def semantic_import_manifest_digest(manifest):
    """Same existing custody identity, excluding only current credential identity."""
    return contract_digest(
        {
            **manifest,
            "principal": {
                key: value
                for key, value in manifest["principal"].items()
                if key != "credential_id"
            },
        }
    )
